CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_staff_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); RETURN new; END $$;
CREATE TRIGGER create_staff_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_staff_profile();
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('staff','admin')),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('staff','admin')) $$;
REVOKE ALL ON FUNCTION public.is_staff() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_staff() TO authenticated;
CREATE TABLE public.inquiries (
id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(),call_started_at timestamptz,call_ended_at timestamptz,call_duration_sec integer DEFAULT 180,channel text NOT NULL DEFAULT 'voice agent',after_hours boolean NOT NULL DEFAULT true,guest_name text NOT NULL,contact text NOT NULL,nationality text,age integer,gender text,language text DEFAULT 'English',type_of_holiday text,reason_for_stay text,check_in date NOT NULL,check_out date NOT NULL,nights integer NOT NULL,adults integer DEFAULT 2,children integer DEFAULT 0,arrival_time text,preferred_check_in_time text DEFAULT '15:00',preferred_check_out_time text DEFAULT '11:00',room_requested text,budget numeric,recommended_room text NOT NULL,recommended_extra text,extras_interested text[] DEFAULT '{}',special_requests text,estimated_value numeric NOT NULL,priority text NOT NULL DEFAULT 'warm' CHECK(priority IN ('hot','warm','cold')),hesitation_reason text,win_back_action text,next_step text,next_step_deadline timestamptz,availability_status text NOT NULL DEFAULT 'to confirm' CHECK(availability_status IN ('to confirm','confirmed','not available')),status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','booked','lost')),decision_time_minutes integer,summary text,transcript jsonb NOT NULL DEFAULT '[]',is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.inquiries TO anon; GRANT SELECT,UPDATE ON public.inquiries TO authenticated; GRANT ALL ON public.inquiries TO service_role;
ALTER TABLE public.inquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY demo_inquiry_read ON public.inquiries FOR SELECT TO anon,authenticated USING(is_demo);
CREATE POLICY staff_inquiry_read ON public.inquiries FOR SELECT TO authenticated USING(public.is_staff());
CREATE POLICY staff_inquiry_update ON public.inquiries FOR UPDATE TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE TABLE public.bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inquiry_id uuid REFERENCES public.inquiries(id),channel text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),check_in date NOT NULL,check_out date NOT NULL,nights integer NOT NULL,room text NOT NULL,extras text[] DEFAULT '{}',total_value numeric NOT NULL,commission_rate numeric NOT NULL DEFAULT 0,commission_cost numeric NOT NULL DEFAULT 0,decision_time_minutes integer,nationality text,age integer,gender text,type_of_holiday text,reason_for_stay text,is_demo boolean NOT NULL DEFAULT false,UNIQUE(inquiry_id));
GRANT SELECT ON public.bookings TO anon; GRANT SELECT ON public.bookings TO authenticated; GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY demo_booking_read ON public.bookings FOR SELECT TO anon,authenticated USING(is_demo);
CREATE POLICY staff_booking_read ON public.bookings FOR SELECT TO authenticated USING(public.is_staff());
CREATE INDEX inquiries_created_idx ON public.inquiries(created_at DESC); CREATE INDEX bookings_created_idx ON public.bookings(created_at DESC);
ALTER PUBLICATION supabase_realtime ADD TABLE public.inquiries;
CREATE FUNCTION public.record_inquiry_booking() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.status='booked' AND old.status<>'booked' THEN new.decision_time_minutes=greatest(0,extract(epoch FROM(now()-new.created_at))/60)::integer; INSERT INTO public.bookings(inquiry_id,channel,check_in,check_out,nights,room,extras,total_value,decision_time_minutes,nationality,age,gender,type_of_holiday,reason_for_stay,is_demo) VALUES(new.id,'voice agent',new.check_in,new.check_out,new.nights,new.recommended_room,new.extras_interested,new.estimated_value,new.decision_time_minutes,new.nationality,new.age,new.gender,new.type_of_holiday,new.reason_for_stay,new.is_demo) ON CONFLICT(inquiry_id) DO NOTHING; END IF; RETURN new; END $$;
CREATE TRIGGER inquiry_booked BEFORE UPDATE OF status ON public.inquiries FOR EACH ROW EXECUTE FUNCTION public.record_inquiry_booking();